('nordvpn','NordVPN','N','linear-gradient(135deg,#2f6bff,#4b8bff)','VPN & Security','','NordVPN protects your connection with military-grade encryption and thousands of servers worldwide.','NordVPN gives you secure, high-speed access with threat protection and thousands of global servers.','Encrypts your internet traffic, hides your IP, and unblocks content across a global server network.','Anyone who values privacy, streamers, and remote workers.',0,0,'','["Military-grade encryption", "Thousands of servers", "Threat protection", "No-logs policy"]'::jsonb,'["6 device connections", "Threat Protection", "Global servers", "Kill switch", "Fast speeds"]'::jsonb,'["Top-tier security", "Huge server network", "Fast streaming"]'::jsonb,'["Private browsing", "Streaming abroad", "Public Wi-Fi safety", "Bypass restrictions"]'::jsonb,105,true,'active'),
